1	<!DOCTYPE html>
2	<html lang="zh-CN">
3	<head>
4	    <meta charset="UTF-8">
5	    <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	    <title>手势控制 · 3D球形相册</title>
7	    <style>
8	        * { margin: 0; padding: 0; box-sizing: border-box; }
9	
10	        body {
11	            overflow: hidden;
12	            background: #000010;
13	            font-family: 'Segoe UI', 'PingFang SC', 'Microsoft YaHei', sans-serif;
14	            user-select: none;
15	            -webkit-user-select: none;
16	            cursor: default;
17	        }
18	
19	        canvas#three-canvas {
20	            display: block;
21	            position: fixed;
22	            top: 0; left: 0;
23	            width: 100vw; height: 100vh;
24	        }
25	
26	        /* 隐藏的摄像头视频元素 */
27	        video#cam-video {
28	            position: fixed;
29	            top: 10px; right: 10px;
30	            width: 160px;
31	            height: 120px;
32	            opacity: 0.15;
33	            border-radius: 8px;
34	            z-index: 100;
35	            transform: scaleX(-1);
36	            pointer-events: none;
37	            border: 1px solid rgba(255,255,255,0.15);
38	        }
39	
40	        /* 上传按钮 */
41	        .upload-wrapper {
42	            position: fixed;
43	            bottom: 36px;
44	            left: 50%;
45	            transform: translateX(-50%);
46	            z-index: 10;
47	            display: flex;
48	            gap: 12px;
49	        }
50	
51	        .btn {
52	            padding: 12px 30px;
53	            border-radius: 50px;
54	            font-size: 15px;
55	            border: 1px solid rgba(255,255,255,0.25);
56	            background: rgba(255,255,255,0.08);
57	            backdrop-filter: blur(12px);
58	            -webkit-backdrop-filter: blur(12px);
59	            color: #fff;
60	            cursor: pointer;
61	            transition: all 0.35s;
62	            letter-spacing: 0.5px;
63	            white-space: nowrap;
64	        }
65	
66	        .btn:hover {
67	            background: rgba(255,255,255,0.18);
68	            border-color: rgba(255,255,255,0.5);
69	            box-shadow: 0 0 30px rgba(120, 100, 255, 0.25);
70	        }
71	
72	        .btn.primary {
73	            background: rgba(120, 100, 255, 0.25);
74	            border-color: rgba(150, 130, 255, 0.5);
75	        }
76	
77	        #file-input { display: none; }
78	
79	        /* 提示文字 */
80	        .hint {
81	            position: fixed;
82	            bottom: 110px;
83	            left: 50%;
84	            transform: translateX(-50%);
85	            z-index: 10;
86	            color: rgba(255,255,255,0.55);
87	            font-size: 13px;
88	            text-align: center;
89	            transition: opacity 0.8s;
90	            pointer-events: none;
91	            letter-spacing: 0.3px;
92	        }
93	
94	        /* 手势状态指示 */
95	        .gesture-indicator {
96	            position: fixed;
97	            top: 24px;
98	            left: 50%;
99	            transform: translateX(-50%);
100	            z-index: 10;
101	            display: flex;
102	            align-items: center;
103	            gap: 8px;
104	            pointer-events: none;
105	        }
106	
107	        .gesture-dot {
108	            width: 8px; height: 8px;
109	            border-radius: 50%;
110	            background: #ff5555;
111	            transition: background 0.4s;
112	        }
113	        .gesture-dot.active { background: #55ff55; box-shadow: 0 0 12px #55ff55; }
114	
115	        .gesture-text {
116	            color: rgba(255,255,255,0.5);
117	            font-size: 12px;
118	            transition: color 0.4s;
119	        }
120	        .gesture-text.active { color: rgba(180,255,180,0.9); }
121	
122	        /* 响应式 */
123	        @media (max-width: 600px) {
124	            .btn { padding: 10px 20px; font-size: 13px; }
125	            .hint { font-size: 11px; bottom: 95px; }
126	            .upload-wrapper { bottom: 24px; gap: 8px; }
127	        }
128	    </style>
129	</head>
130	<body>
131	
132	    <!-- Three.js 渲染目标 -->
133	    <canvas id="three-canvas"></canvas>
134	
135	    <!-- 隐藏的摄像头视频（用于 MediaPipe） -->
136	    <video id="cam-video" autoplay playsinline></video>
137	
138	    <!-- 隐藏的文件上传 input -->
139	    <input type="file" id="file-input" accept="image/*" multiple>
140	
141	    <!-- UI -->
142	    <div class="gesture-indicator">
143	        <div class="gesture-dot" id="gesture-dot"></div>
144	        <span class="gesture-text" id="gesture-text">等待摄像头…</span>
145	    </div>
146	
147	    <div class="hint" id="hint">
148	        ✋ 手掌拖动旋转 &nbsp;|&nbsp; 🤏 捏合缩放 &nbsp;|&nbsp; ✨ 指尖粒子拖尾
149	    </div>
150	
151	    <div class="upload-wrapper">
152	        <button class="btn primary" id="upload-btn">📷 上传照片</button>
153	        <button class="btn" id="reset-btn">🔄 默认纹理</button>
154	    </div>
155	
156	    <!-- ==================== CDN 脚本 ==================== -->
157	    <script src="https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.min.js">
158	    </script>
159	    <script src="https://cdn.jsdelivr.net/npm/@mediapipe/camera_utils@0.3.1675466862/camera_utils.js">
160	    </script>
161	    <script src="https://cdn.jsdelivr.net/npm/@mediapipe/hands@0.4.1675469240/hands.js">
162	    </script>
163	
164	    <script>
165	        // ==================== DOM 引用 ====================
166	        const canvas3d = document.getElementById('three-canvas');
167	        const videoEl = document.getElementById('cam-video');
168	        const fileInput = document.getElementById('file-input');
169	        const uploadBtn = document.getElementById('upload-btn');
170	        const resetBtn = document.getElementById('reset-btn');
171	        const hintEl = document.getElementById('hint');
172	        const gestureDot = document.getElementById('gesture-dot');
173	        const gestureText = document.getElementById('gesture-text');
174	
175	        // ==================== THREE.JS 场景 ====================
176	        const renderer = new THREE.WebGLRenderer({ canvas: canvas3d, antialias: true, alpha: false });
177	        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
178	        renderer.setSize(window.innerWidth, window.innerHeight);
179	        renderer.toneMapping = THREE.ACESFilmicToneMapping;
180	        renderer.toneMappingExposure = 1.2;
181	
182	        const scene = new THREE.Scene();
183	        scene.background = new THREE.Color(0x000010);
184	        scene.fog = new THREE.FogExp2(0x000010, 0.00008);
185	
186	        const camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.5, 50);
187	        camera.position.set(0, 0.3, 6.5);
188	        camera.lookAt(0, 0, 0);
189	
190	        // ==================== 光照 ====================
191	        scene.add(new THREE.AmbientLight(0x334466, 2.5));
192	        const sunLight = new THREE.DirectionalLight(0xffffff, 3.5);
193	        sunLight.position.set(10, 5, 8);
194	        scene.add(sunLight);
195	        const fillLight = new THREE.DirectionalLight(0x4466aa, 1.2);
196	        fillLight.position.set(-5, -2, -4);
197	        scene.add(fillLight);
198	
199	        // ==================== 星空背景 ====================
200	        const starsGeo = new THREE.BufferGeometry();
201	        const STAR_COUNT = 2200;
202	        const starsPos = new Float32Array(STAR_COUNT * 3);
203	        const starsCol = new Float32Array(STAR_COUNT * 3);
204	        const starsSizes = new Float32Array(STAR_COUNT);
205	
206	        for (let i = 0; i < STAR_COUNT; i++) {
207	            // 球形分布
208	            const theta = Math.random() * Math.PI * 2;
209	            const phi = Math.acos(2 * Math.random() - 1);
210	            const r = 10 + Math.random() * 22;
211	            starsPos[i * 3] = r * Math.sin(phi) * Math.cos(theta);
212	            starsPos[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
213	            starsPos[i * 3 + 2] = r * Math.cos(phi);
214	
215	            // 颜色：白色到蓝白色
216	            const temp = 0.6 + Math.random() * 0.4;
217	            starsCol[i * 3] = 0.7 + Math.random() * 0.3;
218	            starsCol[i * 3 + 1] = 0.75 + Math.random() * 0.25;
219	            starsCol[i * 3 + 2] = 0.85 + Math.random() * 0.15;
220	
221	            starsSizes[i] = 0.3 + Math.random() * 1.8;
222	        }
223	
224	        starsGeo.setAttribute('position', new THREE.BufferAttribute(starsPos, 3));
225	        starsGeo.setAttribute('color', new THREE.BufferAttribute(starsCol, 3));
226	        starsGeo.setAttribute('size', new THREE.BufferAttribute(starsSizes, 1));
227	
228	        const starsMat = new THREE.PointsMaterial({
229	            size: 0.06,
230	            vertexColors: true,
231	            blending: THREE.AdditiveBlending,
232	            depthWrite: false,
233	            transparent: true,
234	            opacity: 0.85,
235	            sizeAttenuation: true,
236	        });
237	        const starfield = new THREE.Points(starsGeo, starsMat);
238	        scene.add(starfield);
239	
240	        // ==================== 纹理生成（默认 + 照片拼贴） ====================
241	        const TEX_W = 2048;
242	        const TEX_H = 1024;
243	
244	        function createDefaultTexture() {
245	            const c = document.createElement('canvas');
246	            c.width = TEX_W;
247	            c.height = TEX_H;
248	            const ctx = c.getContext('2d');
249	
250	            // 深色基底
251	            ctx.fillStyle = '#12122a';
252	            ctx.fillRect(0, 0, TEX_W, TEX_H);
253	
254	            // 随机彩色方块拼贴
255	            const cols = 16;
256	            const rows = 8;
257	            const cw = TEX_W / cols;
258	            const rh = TEX_H / rows;
259	
260	            for (let row = 0; row < rows; row++) {
261	                for (let col = 0; col < cols; col++) {
262	                    const hue = (col / cols * 360 + row * 20 + Math.random() * 40) % 360;
263	                    const sat = 40 + Math.random() * 40;
264	                    const light = 20 + Math.random() * 25;
265	                    ctx.fillStyle = `hsl(${hue}, ${sat}%, ${light}%)`;
266	                    const g = 3;
267	                    ctx.fillRect(col * cw + g, row * rh + g, cw - 2 * g, rh - 2 * g);
268	
269	                    // 微小装饰
270	                    ctx.fillStyle = `hsla(${hue}, ${sat}%, ${light + 15}%, 0.5)`;
271	                    ctx.beginPath();
272	                    ctx.arc(col * cw + cw / 2, row * rh + rh / 2, Math.min(cw, rh) * 0.12, 0, Math.PI * 2);
273	                    ctx.fill();
274	                }
275	            }
276	
277	            // 添加一些发光线
278	            ctx.strokeStyle = 'rgba(255,255,255,0.06)';
279	            ctx.lineWidth = 1;
280	            for (let i = 0; i < 40; i++) {
281	                ctx.beginPath();
282	                const lx = Math.random() * TEX_W;
283	                const ly = Math.random() * TEX_H;
284	                ctx.moveTo(lx, ly);
285	                ctx.lineTo(lx + (Math.random() - 0.5) * 300, ly + (Math.random() - 0.5) * 200);
286	                ctx.stroke();
287	            }
288	
289	            return c;
290	        }
291	
292	        function buildCollageCanvas(images) {
293	            const c = document.createElement('canvas');
294	            c.width = TEX_W;
295	            c.height = TEX_H;
296	            const ctx = c.getContext('2d');
297	
298	            // 深色底
299	            ctx.fillStyle = '#0d0d20';
300	            ctx.fillRect(0, 0, TEX_W, TEX_H);
301	
302	            if (!images || images.length === 0) return c;
303	
304	            const n = images.length;
305	            // 计算网格：尽量接近 2:1
306	            const cols = Math.max(1, Math.round(Math.sqrt(n * 2)));
307	            const rows = Math.ceil(n / cols);
308	            const cellW = TEX_W / cols;
309	            const cellH = TEX_H / rows;
310	            const gap = 4;
311	
312	            for (let i = 0; i < n; i++) {
313	                const img = images[i];
314	                const col = i % cols;
315	                const row = Math.floor(i / cols);
316	                const cx = col * cellW;
317	                const cy = row * cellH;
318	
319	                // object-fit: cover
320	                const scale = Math.max(cellW / img.width, cellH / img.height);
321	                const dw = img.width * scale;
322	                const dh = img.height * scale;
323	                const dx = cx + (cellW - dw) / 2;
324	                const dy = cy + (cellH - dh) / 2;
325	
326	                // 圆角裁剪（模拟）
327	                ctx.save();
328	                ctx.beginPath();
329	                roundedRect(ctx, cx + gap, cy + gap, cellW - 2 * gap, cellH - 2 * gap, 6);
330	                ctx.clip();
331	                ctx.drawImage(img, dx, dy, dw, dh);
332	
333	                // 微妙边框
334	                ctx.strokeStyle = 'rgba(255,255,255,0.08)';
335	                ctx.lineWidth = 1;
336	                ctx.stroke();
337	                ctx.restore();
338	
339	                // 内侧微光
340	                ctx.fillStyle = 'rgba(255,255,255,0.03)';
341	                ctx.fillRect(cx + gap, cy + gap, cellW - 2 * gap, cellH - 2 * gap);
342	            }
343	
344	            return c;
345	        }
346	
347	        function roundedRect(ctx, x, y, w, h, r) {
348	            ctx.moveTo(x + r, y);
349	            ctx.lineTo(x + w - r, y);
350	            ctx.quadraticCurveTo(x + w, y, x + w, y + r);
351	            ctx.lineTo(x + w, y + h - r);
352	            ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
353	            ctx.lineTo(x + r, y + h);
354	            ctx.quadraticCurveTo(x, y + h, x, y + h - r);
355	            ctx.lineTo(x, y + r);
356	            ctx.quadraticCurveTo(x, y, x + r, y);
357	            ctx.closePath();
358	        }
359	
360	        // ==================== 球体 ====================
361	        const sphereGeo = new THREE.SphereGeometry(2.2, 72, 72);
362	        const defaultTexCanvas = createDefaultTexture();
363	        const sphereTex = new THREE.CanvasTexture(defaultTexCanvas);
364	        sphereTex.colorSpace = THREE.SRGBColorSpace;
365	        sphereTex.wrapS = THREE.RepeatWrapping;
366	        sphereTex.wrapU = THREE.RepeatWrapping;
367	
368	        const sphereMat = new THREE.MeshStandardMaterial({
369	            map: sphereTex,
370	            roughness: 0.55,
371	            metalness: 0.05,
372	        });
373	        const sphere = new THREE.Mesh(sphereGeo, sphereMat);
374	        scene.add(sphere);
375	
376	        // 半透明大气光晕
377	        const glowGeo = new THREE.SphereGeometry(2.35, 64, 64);
378	        const glowMat = new THREE.ShaderMaterial({
379	            uniforms: {
380	                uTime: { value: 0 },
381	                uColor: { value: new THREE.Color(0x4466cc) },
382	            },
383	            vertexShader: /* glsl */ `
384	                varying vec3 vNormal;
385	                varying vec3 vPosition;
386	                void main() {
387	                    vec4 worldPos = modelMatrix * vec4(position, 1.0);
388	                    vPosition = worldPos.xyz;
389	                    vNormal = normalize(mat3(modelMatrix) * normal);
390	                    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
391	                }
392	            `,
393	            fragmentShader: /* glsl */ `
394	                varying vec3 vNormal;
395	                varying vec3 vPosition;
396	                uniform float uTime;
397	                uniform vec3 uColor;
398	                void main() {
399	                    vec3 viewDir = normalize(cameraPosition - vPosition);
400	                    float fresnel = 1.0 - abs(dot(viewDir, vNormal));
401	                    fresnel = pow(fresnel, 3.5);
402	                    float alpha = fresnel * 0.35;
403	                    gl_FragColor = vec4(uColor, alpha);
404	                }
405	            `,
406	            transparent: true,
407	            depthWrite: false,
408	            blending: THREE.AdditiveBlending,
409	        });
410	        const glowSphere = new THREE.Mesh(glowGeo, glowMat);
411	        scene.add(glowSphere);
412	
413	        // ==================== 粒子拖尾系统 ====================
414	        const MAX_PARTICLES = 600;
415	        const particlePositions = new Float32Array(MAX_PARTICLES * 3);
416	        const particleColors = new Float32Array(MAX_PARTICLES * 3);
417	        const particleSizes = new Float32Array(MAX_PARTICLES);
418	
419	        // 初始化所有粒子在屏幕外
420	        for (let i = 0; i < MAX_PARTICLES; i++) {
421	            particlePositions[i * 3 + 1] = -999;
422	            particleSizes[i] = 0;
423	        }
424	
425	        const particlesGeo = new THREE.BufferGeometry();
426	        particlesGeo.setAttribute('position', new THREE.BufferAttribute(particlePositions, 3));
427	        particlesGeo.setAttribute('color', new THREE.BufferAttribute(particleColors, 3));
428	        particlesGeo.setAttribute('size', new THREE.BufferAttribute(particleSizes, 1));
429	
430	        // 生成发光圆点纹理
431	        function makeGlowSprite() {
432	            const sz = 64;
433	            const c = document.createElement('canvas');
434	            c.width = sz;
435	            c.height = sz;
436	            const ctx = c.getContext('2d');
437	            const grad = ctx.createRadialGradient(sz / 2, sz / 2, 0, sz / 2, sz / 2, sz / 2);
438	            grad.addColorStop(0, 'rgba(255,255,255,1)');
439	            grad.addColorStop(0.08, 'rgba(255,230,180,0.95)');
440	            grad.addColorStop(0.25, 'rgba(255,160,60,0.7)');
441	            grad.addColorStop(0.5, 'rgba(255,100,20,0.25)');
442	            grad.addColorStop(0.75, 'rgba(255,40,0,0.04)');
443	            grad.addColorStop(1, 'rgba(0,0,0,0)');
444	            ctx.fillStyle = grad;
445	            ctx.fillRect(0, 0, sz, sz);
446	            return new THREE.CanvasTexture(c);
447	        }
448	
449	        const particlesMat = new THREE.PointsMaterial({
450	            size: 0.2,
451	            map: makeGlowSprite(),
452	            blending: THREE.AdditiveBlending,
453	            depthWrite: false,
454	            vertexColors: true,
455	            transparent: true,
456	        });
457	        const particleSystem = new THREE.Points(particlesGeo, particlesMat);
458	        scene.add(particleSystem);
459	
460	        // 活跃粒子池
461	        const activeParticles = [];
462	
463	        function spawnParticle(x, y, z) {
464	            const p = {
465	                pos: new THREE.Vector3(x, y, z),
466	                vel: new THREE.Vector3(
467	                    (Math.random() - 0.5) * 0.7,
468	                    (Math.random() - 0.5) * 0.7,
469	                    (Math.random() - 0.5) * 0.7
470	                ),
471	                life: 1.0,
472	                decay: 0.7 + Math.random() * 1.5,
473	                size: 0.04 + Math.random() * 0.16,
474	                hue: 0.08 + Math.random() * 0.1,
475	            };
476	            activeParticles.push(p);
477	            if (activeParticles.length > MAX_PARTICLES) {
478	                activeParticles.shift();
479	            }
480	        }
481	
482	        function updateParticles(dt) {
483	            for (let i = activeParticles.length - 1; i >= 0; i--) {
484	                const p = activeParticles[i];
485	                p.life -= p.decay * dt;
486	                p.pos.x += p.vel.x * dt;
487	                p.pos.y += p.vel.y * dt;
488	                p.pos.z += p.vel.z * dt;
489	                // 轻微阻力
490	                p.vel.multiplyScalar(1 - 1.5 * dt);
491	                if (p.life <= 0) {
492	                    activeParticles.splice(i, 1);
493	                }
494	            }
495	
496	            // 刷新 GPU buffer
497	            for (let i = 0; i < MAX_PARTICLES; i++) {
498	                const idx3 = i * 3;
499	                if (i < activeParticles.length) {
500	                    const p = activeParticles[i];
501	                    particlePositions[idx3] = p.pos.x;
502	                    particlePositions[idx3 + 1] = p.pos.y;
503	                    particlePositions[idx3 + 2] = p.pos.z;
504	                    const alpha = p.life;
505	                    const col = new THREE.Color().setHSL(p.hue, 1, 0.4 + alpha * 0.6);
506	                    particleColors[idx3] = col.r * alpha;
507	                    particleColors[idx3 + 1] = col.g * alpha;
508	                    particleColors[idx3 + 2] = col.b * alpha;
509	                    particleSizes[i] = p.size * alpha;
510	                } else {
511	                    particlePositions[idx3 + 1] = -999;
512	                    particleSizes[i] = 0;
513	                }
514	            }
515	            particlesGeo.attributes.position.needsUpdate = true;
516	            particlesGeo.attributes.color.needsUpdate = true;
517	            particlesGeo.attributes.size.needsUpdate = true;
518	        }
519	
520	        // ==================== 屏幕坐标 → 3D 世界坐标 ====================
521	        function screenToWorld(nx, ny, targetZ = 1.0) {
522	            // nx, ny: MediaPipe 归一化坐标 (0-1)
523	            const vFov = camera.fov * Math.PI / 180;
524	            const dist = camera.position.z - targetZ;
525	            const visH = 2 * Math.tan(vFov / 2) * dist;
526	            const visW = visH * camera.aspect;
527	            // 翻转 Y（MediaPipe Y 向下，Three.js Y 向上）
528	            return new THREE.Vector3(
529	                (nx - 0.5) * visW,
530	                (0.5 - ny) * visH,
531	                targetZ
532	            );
533	        }
534	
535	        // ==================== 手势状态 ====================
536	        const gestureState = {
537	            handDetected: false,
538	            palmX: 0.5, // 归一化 0-1
539	            palmY: 0.5,
540	            prevPalmX: 0.5,
541	            prevPalmY: 0.5,
542	            pinchDist: 0.08, // 归一化 pinch 距离
543	            prevPinchDist: 0.08,
544	            fingertipX: 0.5,
545	            fingertipY: 0.5,
546	            // 平滑后的旋转速度
547	            rotSpeedY: 0,
548	            rotSpeedX: 0,
549	            // 球体缩放
550	            targetScale: 1.0,
551	            currentScale: 1.0,
552	        };
553	
554	        function resetGestureState() {
555	            gestureState.handDetected = false;
556	            gestureState.rotSpeedY = 0;
557	            gestureState.rotSpeedX = 0;
558	            gestureState.targetScale = 1.0;
559	        }
560	
561	        // ==================== MediaPipe Hands 回调 ====================
562	        function onHandsResults(results) {
563	            if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
564	                const lm = results.multiHandLandmarks[0]; // 只用第一只手
565	
566	                // 手掌中心：取手腕(0) + 中指掌指关节(9) 的中点
567	                const wrist = lm[0];
568	                const midMcp = lm[9];
569	                const palmX = (wrist.x + midMcp.x) / 2;
570	                const palmY = (wrist.y + midMcp.y) / 2;
571	
572	                // 指尖：食指指尖(8)
573	                const indexTip = lm[8];
574	                const fingertipX = indexTip.x;
575	                const fingertipY = indexTip.y;
576	
577	                // 捏合检测：拇指尖(4) ↔ 食指尖(8)
578	                const thumbTip = lm[4];
579	                const indexTip2 = lm[8];
580	                const dx = thumbTip.x - indexTip2.x;
581	                const dy = thumbTip.y - indexTip2.y;
582	                const pinchDist = Math.sqrt(dx * dx + dy * dy);
583	
584	                if (!gestureState.handDetected) {
585	                    // 首次检测到手
586	                    gestureState.prevPalmX = palmX;
587	                    gestureState.prevPalmY = palmY;
588	                    gestureState.prevPinchDist = pinchDist;
589	                }
590	
591	                gestureState.handDetected = true;
592	                gestureState.palmX = palmX;
593	                gestureState.palmY = palmY;
594	                gestureState.pinchDist = pinchDist;
595	                gestureState.fingertipX = fingertipX;
596	                gestureState.fingertipY = fingertipY;
597	
598	            } else {
599	                gestureState.handDetected = false;
600	            }
601	        }
602	
603	        // ==================== 初始化 MediaPipe ====================
604	        let handsInstance = null;
605	        let cameraUtils = null;
606	
607	        async function initMediaPipe() {
608	            try {
609	                const { Hands } = window;
610	                if (!Hands) {
611	                    throw new Error('MediaPipe Hands 未加载');
612	                }
613	
614	                handsInstance = new Hands({
615	                    locateFile: (file) =>
616	                        `https://cdn.jsdelivr.net/npm/@mediapipe/hands@0.4.1675469240/${file}`,
617	                });
618	
619	                handsInstance.setOptions({
620	                    maxNumHands: 1,
621	                    modelComplexity: 1,
622	                    minDetectionConfidence: 0.7,
623	                    minTrackingConfidence: 0.6,
624	                });
625	
626	                handsInstance.onResults(onHandsResults);
627	
628	                // 启动摄像头
629	                const stream = await navigator.mediaDevices.getUserMedia({
630	                    video: { width: 640, height: 480, facingMode: 'user' },
631	                });
632	                videoEl.srcObject = stream;
633	                await videoEl.play();
634	
635	                // 使用 MediaPipe Camera utils
636	                const { Camera } = window;
637	                if (Camera) {
638	                    cameraUtils = new Camera(videoEl, {
639	                        onFrame: async () => {
640	                            if (handsInstance) {
641	                                await handsInstance.send({ image: videoEl });
642	                            }
643	                        },
644	                        width: 640,
645	                        height: 480,
646	                    });
647	                    cameraUtils.start();
648	                } else {
649	                    // 降级：手动循环
650	                    async function manualLoop() {
651	                        if (handsInstance && videoEl.readyState >= 2) {
652	                            await handsInstance.send({ image: videoEl });
653	                        }
654	                        requestAnimationFrame(() => manualLoop());
655	                    }
656	                    manualLoop();
657	                }
658	
659	                // 更新 UI
660	                gestureDot.classList.add('active');
661	                gestureText.classList.add('active');
662	                gestureText.textContent = '手势已就绪';
663	                console.log('✅ MediaPipe Hands 初始化成功');
664	            } catch (err) {
665	                console.warn('⚠️ 摄像头/MediaPipe 初始化失败:', err.message);
666	                gestureText.textContent = '摄像头未启用（自动旋转模式）';
667	                gestureDot.style.background = '#ffaa00';
668	                gestureDot.style.boxShadow = '0 0 12px #ffaa00';
669	                // 仍可自动旋转 + 鼠标拖拽备用
670	                setupMouseFallback();
671	            }
672	        }
673	
674	        // ==================== 鼠标拖拽备用方案 ====================
675	        function setupMouseFallback() {
676	            let isDragging = false;
677	            let prevMouseX = 0;
678	            let prevMouseY = 0;
679	
680	            canvas3d.addEventListener('mousedown', (e) => {
681	                isDragging = true;
682	                prevMouseX = e.clientX;
683	                prevMouseY = e.clientY;
684	            });
685	            window.addEventListener('mouseup', () => { isDragging = false; });
686	            window.addEventListener('mousemove', (e) => {
687	                if (!isDragging || gestureState.handDetected) return;
688	                const dx = e.clientX - prevMouseX;
689	                const dy = e.clientY - prevMouseY;
690	                gestureState.rotSpeedY = dx * 0.005;
691	                gestureState.rotSpeedX = dy * 0.005;
692	                prevMouseX = e.clientX;
693	                prevMouseY = e.clientY;
694	            });
695	
696	            // 滚轮缩放
697	            canvas3d.addEventListener('wheel', (e) => {
698	                e.preventDefault();
699	                gestureState.targetScale = Math.max(0.5, Math.min(2.5,
700	                    gestureState.targetScale - e.deltaY * 0.001));
701	            }, { passive: false });
702	        }
703	
704	        // ==================== 处理手势输入 ====================
705	        const DEAD_ZONE = 0.12;
706	        const ROT_SENSITIVITY = 4.5;
707	        const SMOOTH_FACTOR = 8.0; // 平滑系数
708	
709	        function processGestures(dt) {
710	            if (gestureState.handDetected) {
711	                // --- 旋转：摇杆模式 + 死区 ---
712	                const offsetX = gestureState.palmX - 0.5;
713	                const offsetY = gestureState.palmY - 0.5;
714	
715	                let targetRotY = 0;
716	                let targetRotX = 0;
717	
718	                if (Math.abs(offsetX) > DEAD_ZONE) {
719	                    const signX = Math.sign(offsetX);
720	                    targetRotY = (offsetX - signX * DEAD_ZONE) / (0.5 - DEAD_ZONE) * ROT_SENSITIVITY * signX;
721	                }
722	                if (Math.abs(offsetY) > DEAD_ZONE) {
723	                    const signY = Math.sign(offsetY);
724	                    targetRotX = (offsetY - signY * DEAD_ZONE) / (0.5 - DEAD_ZONE) * ROT_SENSITIVITY * signY;
725	                }
726	
727	                // 平滑过渡旋转速度
728	                gestureState.rotSpeedY += (targetRotY - gestureState.rotSpeedY) * Math.min(SMOOTH_FACTOR * dt, 1);
729	                gestureState.rotSpeedX += (targetRotX - gestureState.rotSpeedX) * Math.min(SMOOTH_FACTOR * dt, 1);
730	
731	                // --- 缩放：捏合手势 ---
732	                const pinch = gestureState.pinchDist;
733	                // 捏合距离小 = 放大；距离大 = 缩小
734	                const pinchNorm = THREE.MathUtils.clamp(pinch, 0.02, 0.5);
735	                const scaleTarget = THREE.MathUtils.mapLinear(pinchNorm, 0.02, 0.35, 2.0, 0.55);
736	                gestureState.targetScale += (scaleTarget - gestureState.targetScale) * Math.min(6 * dt, 1);
737	                gestureState.targetScale = THREE.MathUtils.clamp(gestureState.targetScale, 0.5, 2.5);
738	
739	                // --- 指尖粒子 ---
740	                const fpWorld = screenToWorld(gestureState.fingertipX, gestureState.fingertipY, 0.8);
741	                // 每帧生成多个粒子形成拖尾
742	                const spawnCount = 4;
743	                for (let i = 0; i < spawnCount; i++) {
744	                    spawnParticle(
745	                        fpWorld.x + (Math.random() - 0.5) * 0.15,
746	                        fpWorld.y + (Math.random() - 0.5) * 0.15,
747	                        fpWorld.z + (Math.random() - 0.5) * 0.15
748	                    );
749	                }
750	
751	                // 更新上一帧
752	                gestureState.prevPalmX = gestureState.palmX;
753	                gestureState.prevPalmY = gestureState.palmY;
754	                gestureState.prevPinchDist = gestureState.pinchDist;
755	
756	                // UI
757	                gestureDot.classList.add('active');
758	                gestureText.classList.add('active');
759	                gestureText.textContent = '✋ 手势控制中';
760	
761	            } else {
762	                // 无手势 → 缓慢衰减到自动旋转
763	                gestureState.rotSpeedY += (0.25 - gestureState.rotSpeedY) * Math.min(1.5 * dt, 1);
764	                gestureState.rotSpeedX += (0 - gestureState.rotSpeedX) * Math.min(2.0 * dt, 1);
765	                gestureState.targetScale += (1.0 - gestureState.targetScale) * Math.min(3.0 * dt, 1);
766	
767	                gestureDot.classList.remove('active');
768	                gestureText.classList.remove('active');
769	                gestureText.textContent = '🔄 自动旋转中';
770	            }
771	
772	            // 平滑球体缩放
773	            gestureState.currentScale +=
774	                (gestureState.targetScale - gestureState.currentScale) * Math.min(6 * dt, 1);
775	        }
776	
777	        // ==================== 图片上传处理 ====================
778	        uploadBtn.addEventListener('click', () => fileInput.click());
779	
780	        fileInput.addEventListener('change', () => {
781	            const files = Array.from(fileInput.files).filter(f => f.type.startsWith('image/'));
782	            if (files.length === 0) return;
783	
784	            const loadPromises = files.map(file => {
785	                return new Promise((resolve) => {
786	                    const reader = new FileReader();
787	                    reader.onload = (e) => {
788	                        const img = new Image();
789	                        img.onload = () => resolve(img);
790	                        img.onerror = () => resolve(null);
791	                        img.src = e.target.result;
792	                    };
793	                    reader.readAsDataURL(file);
794	                });
795	            });
796	
797	            Promise.all(loadPromises).then(images => {
798	                const valid = images.filter(Boolean);
799	                if (valid.length > 0) {
800	                    applyCollageTexture(valid);
801	                    hintEl.textContent = `✅ 已加载 ${valid.length} 张照片 · ✋ 手掌拖动旋转 | 🤏 捏合缩放`;
802	                    hintEl.style.color = 'rgba(150,255,150,0.8)';
803	                }
804	            });
805	
806	            fileInput.value = '';
807	        });
808	
809	        function applyCollageTexture(images) {
810	            const collageCanvas = buildCollageCanvas(images);
811	            const newTex = new THREE.CanvasTexture(collageCanvas);
812	            newTex.colorSpace = THREE.SRGBColorSpace;
813	            newTex.wrapS = THREE.RepeatWrapping;
814	            newTex.wrapT = THREE.RepeatWrapping;
815	
816	            if (sphereMat.map) sphereMat.map.dispose();
817	            sphereMat.map = newTex;
818	            sphereMat.needsUpdate = true;
819	        }
820	
821	        resetBtn.addEventListener('click', () => {
822	            const defaultCanvas = createDefaultTexture();
823	            const newTex = new THREE.CanvasTexture(defaultCanvas);
824	            newTex.colorSpace = THREE.SRGBColorSpace;
825	            if (sphereMat.map) sphereMat.map.dispose();
826	            sphereMat.map = newTex;
827	            sphereMat.needsUpdate = true;
828	            hintEl.textContent = '✋ 手掌拖动旋转 | 🤏 捏合缩放 | ✨ 指尖粒子拖尾';
829	            hintEl.style.color = 'rgba(255,255,255,0.55)';
830	        });
831	
832	        // ==================== 窗口调整 ====================
833	        window.addEventListener('resize', () => {
834	            renderer.setSize(window.innerWidth, window.innerHeight);
835	            camera.aspect = window.innerWidth / window.innerHeight;
836	            camera.updateProjectionMatrix();
837	        });
838	
839	        // ==================== 动画循环 ====================
840	        const clock = new THREE.Clock();
841	        let timeAccum = 0;
842	
843	        function animate() {
844	            requestAnimationFrame(animate);
845	
846	            const dt = Math.min(clock.getDelta(), 0.1); // 防止大帧跳跃
847	            timeAccum += dt;
848	
849	            // 处理手势 → 更新旋转/缩放状态
850	            processGestures(dt);
851	
852	            // 应用旋转到球体
853	            sphere.rotation.y += gestureState.rotSpeedY * dt;
854	            sphere.rotation.x += gestureState.rotSpeedX * dt;
855	
856	            // 限制俯仰角（防止翻转）
857	            sphere.rotation.x = THREE.MathUtils.clamp(sphere.rotation.x, -Math.PI / 2.2, Math.PI / 2.2);
858	
859	            // 应用缩放
860	            sphere.scale.setScalar(gestureState.currentScale);
861	
862	            // 光晕跟随
863	            glowSphere.rotation.copy(sphere.rotation);
864	            glowSphere.scale.copy(sphere.scale);
865	            glowMat.uniforms.uTime.value = timeAccum;
866	
867	            // 星空微动
868	            starfield.rotation.y += dt * 0.015;
869	            starfield.rotation.x += dt * 0.005;
870	
871	            // 粒子更新
872	            updateParticles(dt);
873	
874	            // 渲染
875	            renderer.render(scene, camera);
876	
877	            // 几秒后渐隐提示
878	            if (timeAccum > 8 && hintEl.style.opacity !== '0') {
879	                hintEl.style.transition = 'opacity 3s';
880	                hintEl.style.opacity = '0';
881	            }
882	        }
883	
884	        // ==================== 启动 ====================
885	        function bootstrap() {
