893	            });
894	
895	            // 开始渲染
896	            animate();
897	
898	            console.log('🚀 3D 球形相册已启动');
899	            console.log('   ✋ 手掌拖动 → 旋转球体');
900	            console.log('   🤏 拇指食指捏合 → 缩放球体');
