258	        // ==================== 可调参数 ====================
259	        const CFG = {
260	            cardCount: 45, // 照片卡片数量
261	            particleDensity: 1.0, // 星尘密度倍率 (0.5~2.0)
262	            clusterRadius: 3.2, // 星群半径
