337	            dustCol[i * 3 + 1] = 0.7 + Math.random() * 0.3;
338	            dustCol[i * 3 + 2] = 0.8 + Math.random() * 0.2;
339	            dustSiz[i] = 0.2 + Math.random() * 1.5;
340	        }
341	        dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPos, 3));
342	        dustGeo.setAttribute('color', new THREE.BufferAttribute(dustCol, 3));
343	        const dustMat = new THREE.PointsMaterial({
344	            size: 0.04,
345	            vertexColors: true,
346	            blending: THREE.AdditiveBlending,
347	            depthWrite: false,
348	            transparent: true,
349	            opacity: 0.7,
350	        });
351	        const dustField = new THREE.Points(dustGeo, dustMat);
352	        scene.add(dustField);
353	
354	        // ==================== 卡片纹理生成 ====================
355	        function generateCardTexture(index, total) {
356	            const sz = 256;
357	            const cv = document.createElement('canvas');
358	            cv.width = sz;
359	            cv.height = Math.round(sz * 1.35); // 3:4 比例更像照片
360	            const ctx = cv.getContext('2d');
361	            const w = cv.width,
362	                h = cv.height;
363	
364	            // 深色底
365	            const hue = (index / total * 360 + Math.random() * 40) % 360;
366	            const grad = ctx.createLinearGradient(0, 0, w, h);
367	            grad.addColorStop(0, `hsl(${hue}, 45%, 18%)`);
368	            grad.addColorStop(0.5, `hsl(${hue}, 40%, 14%)`);
369	            grad.addColorStop(1, `hsl(${hue}, 50%, 10%)`);
370	            ctx.fillStyle = grad;
371	            ctx.fillRect(0, 0, w, h);
372	
373	            // 几何装饰
374	            ctx.fillStyle = `hsla(${hue}, 60%, 40%, 0.25)`;
375	            ctx.beginPath();
376	            ctx.arc(w * 0.7, h * 0.25, w * 0.3, 0, Math.PI * 2);
377	            ctx.fill();
378	            ctx.fillStyle = `hsla(${(hue + 40) % 360}, 50%, 35%, 0.2)`;
379	            ctx.beginPath();
380	            ctx.arc(w * 0.25, h * 0.7, w * 0.25, 0, Math.PI * 2);
381	            ctx.fill();
382	
383	            // 细线
384	            ctx.strokeStyle = `hsla(${hue}, 50%, 50%, 0.3)`;
385	            ctx.lineWidth = 1;
386	            for (let i = 0; i < 3; i++) {
387	                ctx.beginPath();
388	                ctx.moveTo(Math.random() * w, Math.random() * h);
389	                ctx.lineTo(Math.random() * w, Math.random() * h);
390	                ctx.stroke();
391	            }
392	
393	            // 白色相纸边框
394	            const border = w * 0.06;
395	            ctx.strokeStyle = 'rgba(255,255,255,0.12)';
396	            ctx.lineWidth = border;
397	            ctx.strokeRect(border / 2, border / 2, w - border, h - border);
398	
399	            // 内阴影
400	            const innerGrad = ctx.createLinearGradient(0, 0, 0, h);
401	            innerGrad.addColorStop(0, 'rgba(255,255,255,0.03)');
402	            innerGrad.addColorStop(0.5, 'rgba(0,0,0,0)');
403	            innerGrad.addColorStop(1, 'rgba(0,0,0,0.3)');
404	            ctx.fillStyle = innerGrad;
405	            ctx.fillRect(0, 0, w, h);
406	
407	            return new THREE.CanvasTexture(cv);
408	        }
409	
410	        function generatePhotoTexture(img) {
411	            const sz = 256;
412	            const cv = document.createElement('canvas');
413	            cv.width = sz;
414	            cv.height = Math.round(sz * 1.35);
