        card.mesh.scale.lerp(selOriginal.scale, 0.15);
        card.mesh.rotation.x += (selOriginal.rot.x - card.mesh.rotation.x) * 0.15;
        card.mesh.rotation.y += (selOriginal.rot.y - card.mesh.rotation.y) * 0.15;
        card.mesh.rotation.z += (selOriginal.rot.z - card.mesh.rotation.z) * 0.15;
        if (card.mesh.position.distanceTo(selOriginal.pos) < 0.05) {
            card.mesh.position.copy(selOriginal.pos);
            card.mesh.rotation.copy(selOriginal.rot);
            card.mesh.scale.copy(selOriginal.scale);
            selOriginal = null;
        }
    }
}

