426	            const r = SPRITE_SZ / 2;
427	
428	            // 圆形裁剪
429	            ctx.beginPath();
430	            ctx.arc(r, r, r - 3, 0, Math.PI * 2);
431	            ctx.clip();
432	            ctx.drawImage(sourceCanvas, 0, 0, SPRITE_SZ, SPRITE_SZ);
433	
434	            // 羽化光环
435	            ctx.restore = function () {}; // no-op, 用新canvas
436	            const cv2 = document.createElement('canvas');
437	            cv2.width = SPRITE_SZ;
438	            cv2.height = SPRITE_SZ;
439	            const ctx2 = cv2.getContext('2d');
440	
441	            // 径向往外渐变：中心实 → 边缘透明
442	            const grad = ctx2.createRadialGradient(r, r, r * 0.75, r, r, r);
443	            grad.addColorStop(0, 'rgba(255,255,255,1)');
444	            grad.addColorStop(0.8, 'rgba(255,255,255,0.9)');
445	            grad.addColorStop(0.95, 'rgba(255,255,255,0.3)');
446	            grad.addColorStop(1, 'rgba(255,255,255,0)');
447	
448	            ctx2.fillStyle = grad;
449	            ctx2.fillRect(0, 0, SPRITE_SZ, SPRITE_SZ);
